package grading.style;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Stream;

/**
 * The instructor's template sources (the starter code students are given), found by file name. Used
 * to tell a student's own code from the lines they kept unchanged from the template.
 */
public final class Templates {

    private final Path folder;
    private final Map<String, Optional<Path>> files = new HashMap<>();

    /** @param folder the template folder; it may be missing, in which case no file has a template */
    public Templates(Path folder) {
        this.folder = folder;
    }

    /** The template file with this name, such as Q1a.java, ignoring letter case. */
    public synchronized Optional<Path> find(String fileName) {
        return files.computeIfAbsent(fileName.toLowerCase(Locale.ROOT), name -> {
            if (folder == null || !Files.isDirectory(folder)) {
                return Optional.empty();
            }
            try (Stream<Path> paths = Files.walk(folder)) {
                return paths.filter(Files::isRegularFile)
                        .filter(path -> path.getFileName().toString().toLowerCase(Locale.ROOT).equals(name))
                        .findFirst();
            } catch (IOException exception) {
                return Optional.empty();
            }
        });
    }

    /**
     * The 1-based numbers of the student's lines kept unchanged from the template of the same name.
     *
     * @throws IOException if the template exists but cannot be read
     */
    public Set<Integer> keptLines(String fileName, List<String> studentLines) throws IOException {
        Optional<Path> template = find(fileName);
        if (template.isEmpty()) {
            return Set.of();
        }
        return TemplateLines.kept(studentLines, Files.readAllLines(template.get(), StandardCharsets.UTF_8));
    }
}
